const URL = "https://personal-record-3rsq.onrender.com";

type LoginPayload = {
    userId: string;
    password: string;
}

export async function userLogin(data: LoginPayload) {
    const response = await fetch(`${URL}/user/login`, {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
    });

    return await response.json();
}

export async function checkUserLogin(token: string) {
    const response = await fetch(`${URL}/user/auth`, {
        method: "GET",
        headers: {
            "Authorization": `Bearer ${token}`
        }
    });

    return await response.json();
}

export async function foodAnalyze(formData: FormData) {
    const response = await fetch(`${URL}/protein/analyze`, {
        method: "POST",
        body: formData,
    });

    return await response.json();
}
